<script setup lang="ts">import{Head,Link,useForm}from'@inertiajs/vue3';import{ArrowLeft,Camera,CheckCircle2,MapPin,Navigation,UserCheck}from'@lucide/vue';import AppLayout from '@/Layouts/AppLayout.vue';defineProps<{today:any,hasStaff:boolean}>();const f=useForm({locationLabel:'Kantor',latitude:null as number|null,longitude:null as number|null,photo:null as File|null});const locate=()=>navigator.geolocation?.getCurrentPosition(x=>{f.latitude=x.coords.latitude;f.longitude=x.coords.longitude});const file=(e:Event)=>f.photo=(e.target as HTMLInputElement).files?.[0]||null;</script>
<template><Head title="Absenku"/><AppLayout><main class="mx-auto max-w-xl space-y-6 p-4"><div class="flex items-center gap-4"><Link href="/dashboard/pegawai/absensi" class="grid h-11 w-11 place-items-center rounded-full hover:bg-pink-500/10"><ArrowLeft/></Link><div><h1 class="text-2xl font-black">Absenku</h1><p class="text-sm text-slate-500">Catat kehadiran menggunakan lokasi dan foto.</p></div></div><div v-if="!hasStaff" class="rounded-2xl bg-rose-500/10 p-6 font-bold text-rose-600">Profil staff tidak ditemukan pada akun ini.</div><section v-else class="overflow-hidden rounded-[2.5rem] bg-white shadow-2xl dark:bg-slate-900"><header class="bg-gradient-to-br from-pink-500 to-rose-500 p-7 text-white"><UserCheck class="h-10 w-10"/><h2 class="mt-4 text-2xl font-black">{{today?.checkIn&&!today?.checkOut?'Absen Pulang':'Absen Masuk'}}</h2><p class="text-sm text-white/80">{{new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}}</p></header><div v-if="today?.checkOut" class="p-8 text-center"><CheckCircle2 class="mx-auto h-16 w-16 text-emerald-500"/><h3 class="mt-4 text-xl font-black">Absensi Hari Ini Selesai</h3><p class="mt-2 text-sm text-slate-500">Masuk dan pulang sudah tercatat.</p></div><form v-else @submit.prevent="f.post('/dashboard/pegawai/absensi',{forceFormData:true})" class="space-y-5 p-7"><label><span class="label"><MapPin class="h-4 w-4"/>Lokasi</span><input v-model="f.locationLabel" required class="h-12 w-full rounded-xl border bg-transparent px-4 font-bold"/></label><button type="button" @click="locate" class="flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-blue-500/10 font-bold text-blue-600"><Navigation class="h-4 w-4"/>Ambil Lokasi GPS</button><div v-if="f.latitude" class="rounded-xl bg-emerald-500/10 p-3 text-center text-xs font-bold text-emerald-600">Lokasi berhasil diperoleh</div><label class="block rounded-2xl border-2 border-dashed p-6 text-center"><Camera class="mx-auto h-8 w-8 text-pink-500"/><span class="mt-2 block font-bold">Ambil Foto Selfie</span><input type="file" accept="image/*" capture="user" @change="file" class="mt-3 text-xs"/></label><button :disabled="f.processing" class="h-14 w-full rounded-2xl bg-pink-500 text-lg font-black text-white shadow-xl shadow-pink-500/20">{{f.processing?'Mengirim...':today?.checkIn?'Kirim Absen Pulang':'Kirim Absen Masuk'}}</button></form></section></main></AppLayout></template><style scoped>.label{display:flex;align-items:center;gap:.5rem;margin-bottom:.5rem;font-size:.7rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:#64748b}</style>
